grammar Typeof {
 @package: typeofprobe
 @whitespace: none
 @nestedCaptures @mapping(Family) @commonField(text) Value ::= @typeof(value) (A | B) @value;
@mapping(Family.A,params=[text]) A ::= 'a' @text;
@mapping(Family.B,params=[text]) B ::= 'b' @text;
 @root @nestedCaptures @mapping(Pair,params=[left,right]) Root ::= Value @left '=' @typeof(left) Value @right;
}
